import numpy as np
def read_xyz(p):
    lines=open(p).read().splitlines()
    n=int(lines[0]); els=[];xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(v) for v in t[1:4]])
    return els, np.array(xyz)
els,P = read_xyz('opt.xyz')
print(len(els), ''.join(sorted(set(els))))
# order same as mol3d.mol H-added order? obabel may reorder. Instead check distances structurally:
# find bridgehead carbons: sp3 C with 3 C neighbors forming cage
import itertools
def bonds(P, tol=1.75):
    n=len(P); B={}
    for i in range(n):
        for j in range(i+1,n):
            d=np.linalg.norm(P[i]-P[j])
            if d<tol and not (els[i]=='H' and els[j]=='H'):
                B.setdefault(i,[]).append(j); B.setdefault(j,[]).append(i)
    return B
